@extends('layouts.app') @section('title','Hasil Ujian') @section('content')@php $max=$attempt->exam->questions->sum('score');$answered=$attempt->answers->whereNotNull('answer')->where('answer','!=','')->count();$correct=$attempt->answers->where('score','>',0)->count(); @endphp<div class="mx-auto max-w-3xl rounded-3xl bg-white p-8 shadow-sm"><div class="text-center"><div class="text-sm font-bold uppercase text-indigo-600">Hasil Ujian</div><h2 class="mt-2 text-3xl font-black">{{$attempt->exam->title}}</h2><div class="mt-6 text-6xl font-black text-indigo-600">{{number_format($attempt->score,0)}}<span class="text-2xl text-slate-400"> / {{number_format($max,0)}}</span></div><p class="mt-2 font-bold {{$attempt->status==='submitted'?'text-amber-600':'text-emerald-600'}}">{{$attempt->status==='submitted'?'Menunggu penilaian esai':'Penilaian selesai'}}</p></div><div class="mt-8 grid grid-cols-2 gap-3 md:grid-cols-4">@foreach(['Benar'=>$correct,'Terjawab'=>$answered,'Tidak dijawab'=>$attempt->exam->questions->count()-$answered,'Durasi'=>($attempt->submitted_at?->diffInMinutes($attempt->started_at)??0).' menit'] as $l=>$v)<div class="rounded-2xl bg-slate-50 p-4 text-center"><div class="text-xl font-black">{{$v}}</div><div class="text-xs text-slate-500">{{$l}}</div></div>@endforeach</div></div>@endsection
